replacements.new:
session.transcribe(locale) {
            model.verify()
            val prepared = WhisperSpeechGate.prepare(model, samples)
            val buffer = java.nio.ByteBuffer.allocate(prepared.size * 4).order(java.nio.ByteOrder.LITTLE_ENDIAN)
            for (index in prepared.indices) buffer.putFloat(prepared[index])
            val digest = java.security.MessageDigest.getInstance("SHA-256").digest(buffer.array())
            val digits = "0123456789abcdef"
            val sha = java.lang.StringBuilder(digest.size * 2)
            for (byteValue in digest) {
                val value = byteValue.toInt() and 0xff
                sha.append(digits[value ushr 4]).append(digits[value and 0x0f])
            }
            val fingerprint = java.io.File(model.directory, "odai-native-parity-prepared.txt")
            check(!fingerprint.exists()) { "prepared fingerprint already present" }
            check(fingerprint.createNewFile()) { "prepared fingerprint create failed" }
            java.io.FileOutputStream(fingerprint).use { output ->
                val payload = "preparedFloat32LeSha256=$sha|preparedSampleCount=${prepared.size}"
                output.write(payload.toByteArray(java.nio.charset.StandardCharsets.UTF_8))
                output.flush()
            }
            prepared
        }
